                if (entry === undefined)
                    return;
                if (this.rendered.nestedGroup.groups[entry.id] == null)
                    continue; // removed
                const cur = this.rendered.treeview.getState(entry.id);
                if (cur != null && cur[0] === 1)
                    continue; // already visible again
                const showEdges = this._studioManager.isActive ? 0 : entry.state[1];
